return [{
  json: {
    _ctx: {
      executionId: $execution.id,
      catalogId:   'AUT-XXXX',
      runDate:     new Intl.DateTimeFormat('pt-BR', {
                     timeZone: 'America/Sao_Paulo',
                     year: 'numeric', month: '2-digit', day: '2-digit'
                   }).format(new Date()),
      environment: 'production',
      startedAt:   new Date().toISOString()
    }
  }
}];

// Monta o e-mail ao COR a partir do payload do backend (evento gmud_lista_cor).
const p = $('01A - Receber Lista de Clientes da GMUD').first().json.body ?? {};
if (p.evento !== 'gmud_lista_cor') throw new Error('Evento inesperado: ' + p.evento);
const destinatarios = (p.destinatarios ?? []).map((d) => String(d.email ?? '').trim()).filter((e) => e.includes('@'));
if (destinatarios.length === 0) throw new Error('Sem destinatários no payload.');

const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const fmt = (s) => {
  const m = /^(\d{4})-(\d{2})-(\d{2}) (\d{2}):(\d{2})/.exec(String(s ?? ''));
  return m ? `${m[3]}/${m[2]}/${m[1]} ${m[4]}:${m[5]}` : '-';
};
const ROTULO = { liberacao: 'GMUD liberada', atualizacao: 'GMUD ATUALIZADA', lembrete: 'Lembrete' };
const rotulo = ROTULO[p.tipo] ?? 'GMUD';
const r = p.resumo ?? {};
const janela = p.janela ? `${fmt(p.janela.inicio)} → ${fmt(p.janela.fim)}` : '-';

const linhas = (p.clientes ?? []).map((c) => {
  const destaque = c.tipo === 'corporativo' ? '' : ' style="background:#fff3d0"';
  return `<tr${destaque}><td>${esc(c.nome)}</td><td>${esc(c.contrato)}</td><td>${esc(c.pppoe) || '-'}</td><td>${esc(c.pontoAcesso) || '-'}</td><td>${esc(c.tipoLabel)}</td></tr>`;
}).join('');

const intro = {
  liberacao: 'A GMUD abaixo foi liberada. Segue a lista de clientes que serão impactados, para o COR se preparar antes da execução.',
  atualizacao: 'A abrangência, os clientes ou a janela desta GMUD mudaram. Esta lista substitui a anterior.',
  lembrete: 'A execução desta GMUD está próxima. Segue a lista de clientes impactados.',
}[p.tipo] ?? '';

const html = `
<div style="font-family:Arial,sans-serif;font-size:14px;color:#222">
  <h2 style="margin:0 0 4px">${esc(rotulo)} — GMUD ${esc(p.protocol)}</h2>
  <p style="margin:0 0 12px;color:#555">${esc(p.titulo)}</p>
  <p>${esc(intro)}</p>
  <table style="border-collapse:collapse;margin:8px 0 12px" cellpadding="4">
    <tr><td><b>Janela</b></td><td>${esc(janela)}</td></tr>
    <tr><td><b>POP/Site</b></td><td>${esc(p.popSite) || '-'}</td></tr>
    <tr><td><b>Abrangência</b></td><td>${esc(p.abrangenciaRede) || 'Site inteiro'}</td></tr>
    <tr><td><b>Solicitante</b></td><td>${esc(p.solicitanteNome)}${p.solicitanteEmail ? ' (' + esc(p.solicitanteEmail) + ')' : ''}</td></tr>
    <tr><td><b>Clientes</b></td><td>${esc(r.total ?? 0)} no total: ${esc(r.corporativos ?? 0)} corporativos, ${esc(r.pontoAPonto ?? 0)} ponto a ponto, ${esc(r.fibraApagada ?? 0)} fibra apagada</td></tr>
  </table>
  <table style="border-collapse:collapse;width:100%" border="1" cellpadding="6">
    <tr style="background:#eee"><th align="left">Cliente</th><th align="left">Contrato</th><th align="left">Usuário</th><th align="left">Ponto de acesso</th><th align="left">Tipo</th></tr>
    ${linhas || '<tr><td colspan="5">Nenhum cliente corporativo ou ponto a ponto nesta GMUD.</td></tr>'}
  </table>
  ${p.link ? `<p style="margin-top:14px"><a href="${esc(p.link)}">Abrir a GMUD na plataforma</a></p>` : ''}
  <p style="color:#888;font-size:12px">A lista completa também segue em anexo (CSV). Enviado automaticamente pelo Monitoramento de Splitters.</p>
</div>`;

const csv = '\uFEFF' + String(p.csv ?? '');
return [{
  json: {
    to: destinatarios.join(','),
    subject: `[GMUD ${p.protocol}] ${rotulo}: lista de clientes impactados — ${p.titulo ?? ''}`.slice(0, 200),
    html,
    protocol: p.protocol,
    tipo: p.tipo,
    total: r.total ?? 0,
  },
  binary: {
    data: await this.helpers.prepareBinaryData(Buffer.from(csv, 'utf8'), `gmud-${p.protocol}-clientes.csv`, 'text/csv'),
  },
}];
